use std::path::Path;

const MARKER: &str = "commit-lint-gen hook";

fn hook_content() -> String {
    format!(
        "#!/bin/sh\n# {}\n# Auto-generated by clg init\n# Validates commit messages against conventional commits format\n\nCOMMIT_MSG_FILE=$1\n\nclg lint \"$(cat \"$COMMIT_MSG_FILE\")\"\n\nexit $?\n",
        MARKER
    )
}

pub fn install(repo: &Path) -> Result<String, String> {
    let git_dir = repo.join(".git");
    if !git_dir.is_dir() {
        return Err(
            "Not a git repository. Run this command from the root of a git repository.".into(),
        );
    }
    let hooks_dir = git_dir.join("hooks");
    std::fs::create_dir_all(&hooks_dir).map_err(|e| e.to_string())?;
    let hook_path = hooks_dir.join("commit-msg");
    std::fs::write(&hook_path, hook_content()).map_err(|e| e.to_string())?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let _ = std::fs::set_permissions(&hook_path, std::fs::Permissions::from_mode(0o755));
    }

    Ok(hook_path.display().to_string())
}

pub fn uninstall(repo: &Path) -> Result<bool, String> {
    let hook_path = repo.join(".git").join("hooks").join("commit-msg");
    if !hook_path.exists() {
        return Ok(false);
    }
    let content = std::fs::read_to_string(&hook_path).map_err(|e| e.to_string())?;
    if !content.contains(MARKER) {
        return Err(
            "The commit-msg hook was not installed by clg. Please remove it manually if needed."
                .into(),
        );
    }
    std::fs::remove_file(&hook_path).map_err(|e| e.to_string())?;
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn temp_repo(name: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "clg-{}-{}-{}",
            name,
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(dir.join(".git")).unwrap();
        dir
    }

    #[test]
    fn install_writes_hook_and_uninstall_removes_it() {
        let repo = temp_repo("hook");
        let path = PathBuf::from(install(&repo).unwrap());
        let content = std::fs::read_to_string(&path).unwrap();
        assert!(content.contains(MARKER));
        assert!(content.contains("clg lint"));
        assert!(install(&repo).is_ok(), "install is idempotent");

        assert!(uninstall(&repo).unwrap());
        assert!(!path.exists());
        assert!(!uninstall(&repo).unwrap(), "nothing to remove");

        std::fs::remove_dir_all(repo).ok();
    }

    #[test]
    fn install_requires_git_repository() {
        let dir = std::env::temp_dir().join(format!("clg-nogit-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        assert!(install(&dir).is_err());
        std::fs::remove_dir_all(dir).ok();
    }

    #[test]
    fn uninstall_refuses_foreign_hook() {
        let repo = temp_repo("foreign");
        let hook = repo.join(".git").join("hooks");
        std::fs::create_dir_all(&hook).unwrap();
        let path = hook.join("commit-msg");
        std::fs::write(&path, "#!/bin/sh\necho custom\n").unwrap();
        assert!(uninstall(&repo).is_err());
        assert!(path.exists());
        std::fs::remove_dir_all(repo).ok();
    }
}
